#include "stdlib/assert/napi/is_type.h"
#include <node_api.h>
#include <stdlib.h>
#include <assert.h>

/**
* Receives JavaScript callback invocation data.
*
* @param env    environment under which the function is invoked
* @param info   callback data
* @return       Node-API value
*/
static napi_value addon( napi_env env, napi_callback_info info ) {
	napi_status status;

	size_t argc = 1;
	napi_value argv[ 1 ];
	status = napi_get_cb_info( env, info, &argc, argv, NULL, NULL );
	assert( status == napi_ok );

	if ( argc != 1 ) {
		status = napi_throw_error( env, NULL, "invalid invocation. Must provide 1 argument." );
		assert( status == napi_ok );
		return NULL;
	}

	napi_value err;
	status = stdlib_assert_napi_value_is_type( env, argv[ 0 ], napi_number, "invalid argument. Must provide a number.", &err );
	assert( status == napi_ok );

	if ( err != NULL ) {
		status = napi_throw( env, err );
		assert( status == napi_ok );
		return NULL;
	}
	return NULL;
}

/**
* Initializes a Node-API module.
*
* @param env      environment under which the function is invoked
* @param exports  exports object
* @return         main export
*/
static napi_value init( napi_env env, napi_value exports ) {
	napi_value fcn;
	napi_status status = napi_create_function( env, "exports", NAPI_AUTO_LENGTH, addon, NULL, &fcn );
	assert( status == napi_ok );
	return fcn;
}

NAPI_MODULE( NODE_GYP_MODULE_NAME, init )","lineStart":1,"lineEnd":71,"totalLines":71,"truncated":false}},"title":"repos/pc-lib-3456/assert-napi-is-type/src/addon.c","time":{"start":1783262576719,"end":1783262576723}},"id":"prt_f32bb7f51001sCDtu1cJMj3OWl","sessionID":"ses_0cd44bfc9ffeq1McF5hIHRwTVF","messageID":"msg_f32bb7604001vGOmdY3BGTmOpf"}}

