'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var tryRequire = require( '@stdlib/utils-try-require' );


// VARIABLES //

var addon = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( addon instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof addon, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if provided argument which is not a number', opts, function test( t ) {
	var values;
	var i;

	values = [
		'5',
		true,
		false,
		null,
		void 0,
		[],
		{}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), Error, 'throws an error when provided '+values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			addon( value );
		};
	}
});

tape( 'the function does not throw an error if provided a number', opts, function test( t ) {
	var values;
	var v;
	var i;

	values = [
		5,
		-5,
		NaN,
		0
	];
	for ( i = 0; i < values.length; i++ ) {
		v = addon( values[ i ] );
		t.strictEqual( v, void 0, 'returns expected value when provided '+values[ i ] );
	}
	t.end();
});","lineStart":1,"lineEnd":85,"totalLines":85,"truncated":false}},"title":"repos/pc-lib-3456/assert-napi-is-type/test/test.native.js","time":{"start":1783262592208,"end":1783262592212}},"id":"prt_f32bbb952001scfLODGbFB5ovR","sessionID":"ses_0cd44bfc9ffeq1McF5hIHRwTVF","messageID":"msg_f32bbae3c00147C9YEC426xPEs"}}

